const ee = require('@google/earthengine');
const privateKey = require('./.earthsense-436113-b294c5f5c2dc.json');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point1 = ee.Geometry.Point([-119.02882425044682, 46.929987337866386]);
  const point2 = ee.Geometry.Point([-119.70997639198902, 43.19114225407087]);
  const startDate = '2015-11-29';
  const endDate = '2015-11-30'; // Narrow window to get imagery for the specific date

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR')
    .filterDate(startDate, endDate)
    .filterBounds(point1.union(point2));

  let collectionSize = await collection.size().getInfo();

  // If no images, try widening the date range slightly for recovery.
  if (collectionSize === 0) {
    console.log("No data for exact date. Widening date range to 3 days around.");
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR')
      .filterDate('2015-11-28', '2015-12-01')
      .filterBounds(point1.union(point2));
    collectionSize = await collection.size().getInfo();
  }

  if (collectionSize === 0) {
    console.log("No images found for the specified date/location.");
    console.log("C1");
    return;
  }

  // Get the first image from the collection.
  const image = collection.first();

  // Define a function to extract QA_PIXEL value at a point and interpret cloudiness.
  // Bits in QA_PIXEL for LANDSAT/LC08/C02/T1_SR (Surface Reflectance):
  // 3: cloud shadow (0 = clear, 1 = cloud shadow)
  // 5: cloud (0 = clear, 1 = cloud)
  // 6-7: cloud confidence (00 = Not Set, 01 = Low, 10 = Medium, 11 = High)
  // We'll consider a pixel cloudy if bit 5 is set, or if cloud confidence is Medium or High.
  const isCloudy = async (img, point) => {
    try {
      const qaValue = await img.reduceRegion({
        reducer: ee.Reducer.first(),
        geometry: point,
        scale: 30, // Landsat 8 resolution
        maxPixels: 1e9
      }).get('QA_PIXEL').getInfo();

      if (qaValue === null || qaValue === undefined) {
        return { status: "C3", message: "QA_PIXEL value is null/undefined at point." };
      }

      // Bit 5 is Cloud.
      // Bits 6-7 are Cloud Confidence: 00=Not Set, 01=Low, 10=Medium, 11=High.
      const cloudBit = (qaValue >> 5) & 1;
      const cloudConfidenceBits = (qaValue >> 6) & 3; // Extract 2 bits

      // Consider cloudy if:
      // - Bit 5 (Cloud) is set.
      // - Or if Cloud Confidence is Medium (10) or High (11).
      const cloudy = cloudBit === 1 || cloudConfidenceBits >= 2; // 2 (10) is Medium, 3 (11) is High

      return { status: "Success", cloudy: cloudy, qa: qaValue };

    } catch (error) {
      console.error("Error processing point:", error);
      return { status: "D", message: `Error getting QA_PIXEL for point: ${error.message}` };
    }
  };

  // Process both points
  let cloudStatus1 = await isCloudy(image, point1);
  let cloudStatus2 = await isCloudy(image, point2);

  if (cloudStatus1.status !== "Success") {
    console.log(cloudStatus1.message);
    console.log(cloudStatus1.status);
    return;
  }
  if (cloudStatus2.status !== "Success") {
    console.log(cloudStatus2.message);
    console.log(cloudStatus2.status);
    return;
  }

  const isPoint1Cloudy = cloudStatus1.cloudy;
  const isPoint2Cloudy = cloudStatus2.cloudy;

  console.log(`Image ID: ${image.id().getInfo()}`);
  console.log(`Date: ${image.date().format('YYYY-MM-dd').getInfo()}`);
  console.log(`Point 1 (${point1.coordinates().getInfo()}): QA_PIXEL=${cloudStatus1.qa}, Cloudy=${isPoint1Cloudy}`);
  console.log(`Point 2 (${point2.coordinates().getInfo()}): QA_PIXEL=${cloudStatus2.qa}, Cloudy=${isPoint2Cloudy}`);

  // 5. Validation & Final Answer
  if (isPoint1Cloudy && isPoint2Cloudy) {
    console.log("A"); // Both locations are covered by clouds or fogs
  } else {
    console.log("B"); // Not both locations are covered by clouds or fogs
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
